wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40704562295911966)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(874709556377097046)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Detail - Save Interactive Grid Data'
,p_static_id=>'detail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begin',
'    if :ITEMCODE is not null then',
'    case :APEX$ROW_STATUS',
'        when ''C'' then',
'            Insert Into salesenquirydetail (                 ',
'                    tno                    ,',
'                    sno                    ,',
'                    itemcode               ,',
'                    itemspecificationcode  ,',
'                    description            ,',
'                    quantity1              ,',
'                    quantity2              ,',
'                    ratemeasuringunitcode  ,',
'                    ',
'                  ',
'                    rate                   ,',
'                    amount                 ,',
'                    footeramount           ,',
'                    totalamount            ,',
'                    remark                 ,',
'                    lowertolerancepercent  ,',
'                    highertolerancepercent ',
'                     ',
'                    --taxrulecode            ',
'            )',
'            Values (',
'                :tno                    ,',
'                :sno                    ,',
'                :itemcode               ,',
'                :itemspecificationcode  ,',
'                :description            ,',
'                :quantity1              ,',
'                :quantity2              ,',
'                :ratemeasuringunitcode  ,',
'              ',
'             ',
'                :rate                   ,',
'                :amount                 ,',
'                :footeramount           ,',
'                :totalamount            ,',
'                :remark                 ,',
'                :lowertolerancepercent  ,',
'                :highertolerancepercent ',
'                   ',
'                  ',
'            );',
'        ',
'        when ''U'' then',
'            update salesenquirydetail Set',
'                    tno                     =		:tno                    ,',
'                    sno                     =		:sno                    ,',
'                    itemcode                =		:itemcode               ,',
'                    itemspecificationcode   =		:itemspecificationcode  ,',
'                    description             =		:description            ,',
'                    quantity1               =		:quantity1              ,',
'                    quantity2               =		:quantity2              ,',
'                    ratemeasuringunitcode   =		:ratemeasuringunitcode  ,',
'                ',
'                    rate                    =		:rate                   ,',
'                    amount                  =		:amount                 ,',
'                    footeramount            =		:footeramount           ,',
'                    totalamount             =		:totalamount            ,',
'                    remark                  =		:remark                 ,',
'                    lowertolerancepercent   =		:lowertolerancepercent  ,',
'                    highertolerancepercent  =		:highertolerancepercent ',
'                  ',
'            WHERE TNO = :P702_TNO',
'              and rowid = :ROWID;',
'',
'        when ''D'' then',
'            Delete From salesenquirydetail',
'            Where TNo = :P702_TNO',
'              and SNO = :SNO',
'              ;',
'    end case;',
'    end if;',
'exception when others then',
'    raise_application_error(-20010, sqlerrm);',
'End;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8662045761502218
);
