wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(41001981777918601)
,p_event_id=>wwv_flow_imp.id(41001417445918601)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_name=>'detail'
,p_static_id=>'detail'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P705_SALESENQUIRYTNO,P705_TNO',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'if :P705_SALESENQUIRYTNO is not null then',
    '    delete from salesquotationdetail where tno = :P705_TNO;',
    '',
    '    for vSenq in (',
    '          select',
    '            ITEMCODE,',
    '            ITEMSPECIFICATIONCODE,',
    '            DESCRIPTION,',
    '            QUANTITY1,',
    '            QUANTITY2,',
    '            RATEMEASURINGUNITCODE,',
    '            RATE,',
    '            AMOUNT,',
    '            FOOTERAMOUNT,',
    '            TOTALAMOUNT,',
    '            REMARK',
    '           ',
    '        from salesenquirydetail a',
    '        where tno = :P705_SALESENQUIRYTNO',
    '        order by sno',
    '    ) loop ',
    '    insert into salesquotationdetail',
    '    (',
    '        TNO,',
    '        SNO,',
    '        ITEMCODE,',
    '        ITEMSPECIFICATIONCODE,',
    '        DESCRIPTION,',
    '        QUANTITY1,',
    '        QUANTITY2,',
    '        RATEMEASURINGUNITCODE,',
    '        RATE,',
    '        AMOUNT,',
    '        FOOTERAMOUNT,',
    '        TOTALAMOUNT,',
    '        Remark',
    '    ) values ',
    '    (',
    '        :P705_TNO,',
    '        globaltno.nextval,',
    '        vSenq.itemcode,',
    '        vSenq.itemspecificationcode,',
    '        vSenq.description,',
    '        vSenq.quantity1,',
    '        vSenq.quantity2,',
    '        vSenq.ratemeasuringunitcode,',
    '        vSenq.rate,',
    '        vSenq.amount,',
    '        vSenq.footeramount,',
    '        vSenq.totalamount,',
    '        vSenq.Remark',
    '    );',
    '  end loop;  ',
    '    ',
    'end if;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
