,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'save detail'
,p_static_id=>'save-detail'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begin',
'    case :APEX$ROW_STATUS',
'        when ''C'' then',
'            Insert Into SALESQUOTATIONDETAIL (                 ',
'                    TNO,',
'SNO,',
'SERIALNO,',
'ITEMCODE,',
'ITEMSPECIFICATIONCODE,',
'DESCRIPTION,',
'QUANTITY1,',
'QUANTITY2,',
'RATEMEASURINGUNITCODE,',
'RATE,',
'AMOUNT,',
'FOOTERAMOUNT,',
'TOTALAMOUNT,',
'REMARK,',
'PACKINGTYPECODE,',
'PACKINGNOS',
'            )',
'            Values (',
'                :TNO,',
':SNO,',
':SERIALNO,',
':ITEMCODE,',
':ITEMSPECIFICATIONCODE,',
':DESCRIPTION,',
':QUANTITY1,',
':QUANTITY2,',
':RATEMEASURINGUNITCODE,',
':RATE,',
':AMOUNT,',
':FOOTERAMOUNT,',
':TOTALAMOUNT,',
':REMARK,',
':PACKINGTYPECODE,',
':PACKINGNOS',
'',
'            );',
'        ',
'        when ''U'' then',
'            update SALESQUOTATIONDETAIL Set',
'                  TNO=:TNO,',
'SNO=:SNO,',
'SERIALNO=:SERIALNO,',
'ITEMCODE=:ITEMCODE,',
'ITEMSPECIFICATIONCODE=:ITEMSPECIFICATIONCODE,',
'DESCRIPTION=:DESCRIPTION,',
'QUANTITY1=:QUANTITY1,',
'QUANTITY2=:QUANTITY2,',
'RATEMEASURINGUNITCODE=:RATEMEASURINGUNITCODE,',
'RATE=:RATE,',
'AMOUNT=:AMOUNT,',
'FOOTERAMOUNT=:FOOTERAMOUNT,',
'TOTALAMOUNT=:TOTALAMOUNT,',
'REMARK=:REMARK,',
'PACKINGTYPECODE=:PACKINGTYPECODE,',
'PACKINGNOS=:PACKINGNOS',
'',
'',
'            WHERE TNO = :P705_TNO',
'              and rowid = :ROWID;',
'',
'        when ''D'' then',
'            Delete From SALESQUOTATIONDETAIL',
'            Where TNo = :P705_TNO',
'              and SNO = :SNO',
'              ;',
'    end case;',
'exception when others then',
'    raise_application_error(-20010, sqlerrm);',
'End;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>8842942652508813
);
